window.INDUSTRY_REPORTS['banks'] = {
  id:'banks', title:'银行行业研究', kicker:'行业研究 · 信用、资本与股东回报',
  subject:'以招商银行为核心样本，讨论中国上市银行的经营与估值；不代表全行业平均',
  author:'刘益的复利研究室', date:'2026年10月1日；财务锚为2026H1',
  summaryTitle:'低PB是否便宜，先看资本回报能否穿越信用周期',
  coreConclusion:'银行不是一门把收入增长直接变成股东现金的生意。低成本、稳定的存款与可信的风险管理，决定银行能否在利率下行和信用波动中保住资本回报；留存利润则必须先支持风险加权资产和资本缓冲。招商银行中报收入、利润增长，但年化普通股ROE与净息差下降、关注类贷款占比上升，说明利润修复与长期回报质量需要分开观察。研究优先看正常化信用损失后的每股资本创造，再看价格是否提供足够回报，而不是仅凭低PB或高股息作买入判断。',
  stats:[{label:'净息差',value:'1.83%',note:'招行集团2026H1，同比−0.05个百分点'},{label:'普通股ROE',value:'13.42%',note:'2026H1年化，非未来承诺'},{label:'核心一级资本',value:'14.07%',note:'期末高级法；权重法11.84%'}],
  nav:[['business','生意'],['facts','中报'],['funding','负债'],['credit','信用'],['capital','资本'],['wealth','财富'],['differences','分化'],['valuation','估值'],['scenarios','情景'],['risks','风险'],['verify','验证']],
  sections:[
    {id:'business',title:'一、银行赚什么钱，又承担什么风险？',sub:'把利差、手续费、投资收益和信用损失拆开',blocks:[
      {p:'银行首先是一张高杠杆资产负债表。客户存款不是营业收入，发放贷款不是生产设备投资，偿还存款也不能与普通企业偿还供应商等同。利息收入减资金成本形成净利息收入，再加手续费和投资等非利息收益，扣除运营费用、信用损失与税，才形成归母利润。这个利润还不一定能分配，因为资产扩张和风险变化会消耗资本。'},
      {table:{head:['经营环节','可能的优势','必须验证的代价'],rows:[['吸收存款','支付与结算形成低成本、稳定资金','定期化、同业竞争、客户集中与重定价'],['发放贷款','客户识别、服务能力和风险定价','违约、抵押品折价、展期与回收时间'],['财富管理','客户关系、渠道和资产配置服务','收费率、市场波动、客户信任与合规'],['金融市场','流动性配置、交易与对客服务','久期、信用利差、估值波动及资金错配']]}},
      {p:'对长期股东，最重要的不是某一年贷款增长多少，而是新增资产能否在扣除完整风险成本后创造超过股权机会成本的回报。如果银行必须持续补资本才能维持增长，表面利润增长与每股财富增长可能分离。规模越大不一定越安全，低不良率也不等于潜在损失已全部揭示。'}]},
    {id:'facts',title:'二、最新中报：经营改善，但并非所有指标都改善',sub:'集团口径、半年累计与期末指标分别标注',blocks:[
      {table:{head:['招商银行指标','2026H1或6月末','可支持的解读'],rows:[['营业收入','1,781.81亿元；同比+4.83%','收入恢复增长'],['归属本行股东净利润','764.45亿元；同比+2.02%','利润增幅低于收入增幅'],['净利息收益率','1.83%；同比−0.05个百分点','利差压力仍存在'],['普通股平均净资产收益率','13.42%（年化）；同比−0.43个百分点','不能把绝对利润增长当ROE改善'],['不良贷款率 / 拨备覆盖率','0.94% / 385.10%','分别与上年末持平 / 下降6.69个百分点'],['关注类贷款占比','1.53%；上年末1.43%','需要跟踪迁徙，不等于全部会转不良'],['核心一级资本充足率','高级法14.07%；权重法11.84%','不同计算方法不可直接混比']],note:'[S1] PDF7、9、23、30页。金额由百万元转为亿元；ROE为公司披露年化值，不把半年利润机械乘二预测全年。净利息收益率与净利差不是同一指标。'}},
      {p:'这些指标组合支持的是“盈利仍具韧性，但需要观察资本回报与信用成本”，不是“整个银行业拐点已经确认”。招商银行只是一个样本，没有以其资产质量和资金成本代表其他银行，也没有从中报推导全行业实时估值。研究中应保留另一种解释：降存款成本、资产规模增长和非利息业务改善，可能暂时抵消资产定价下行；这种抵消能否延续，需要后续原始数据。'},
      {p:'银行报表还存在集团、本行和子公司范围差别。本文采用集团指标；本行单体不良率、零售贷款不良率和集团不良率不可互换。核心一级资本高级法与权重法同时列出，是提醒风险计量选择会影响比率，而不是说二者矛盾。'}]},
    {id:'funding',title:'三、负债优势：便宜的存款比高贷款利率更难复制',sub:'客户关系必须落实为稳定资金，而非昂贵揽储',blocks:[
      {p:'银行可以通过提高贷款收益率暂时改善息差，也可能只是承担了更高风险。相较之下，稳定的结算、工资、消费和企业现金管理关系能带来不完全依赖价格的存款，是更值得研究的竞争优势。但活期存款占比不是永久常量；客户转向定期、理财或货币基金后，同一存款规模对应的成本会变化。'},
      {bullets:['先看存款日均余额、活期与定期结构，再看期末余额；短期冲量不能冒充全年低成本资金。','分析资产与负债重定价时间。贷款利率下调与存款成本下降并不同步，不能只用一次降息预测完整息差路径。','理财与存款既有竞争也有客户留存作用；从存款流向自有渠道理财，并不等于银行拥有该资产本金。','大额企业客户存款要看集中度和稳定性，不能将一笔大额资金长期按低成本续存。']},
      {p:'压力测试应包含两个不利变化同时发生：贷款收益率下降，而客户要求更高存款回报或更短期限。银行可能通过缩短资产久期、减少高风险投放来保护流动性，但这也会压低收入。看银行管理能力，要观察其是否愿意牺牲规模以保住资本，而非每个周期都追逐规模榜单。'}]},
    {id:'credit',title:'四、信用成本：风险常在好看的利润之后出现',sub:'不良、关注、逾期、核销与回收共同组成证据链',blocks:[
      {p:'不良率是存量指标，可能被新贷款扩大分母、核销和转让影响。关注贷款、逾期与不良生成提供另一部分信息；拨备覆盖率是账面准备相对已认定不良的比值，不是任意分给股东的现金。研究不能简单说“拨备高，所以未来一定可以释放利润”，因为潜在信用损失、监管要求和经营判断都会制约释放。'},
      {table:{head:['需要分开看的项目','看什么','容易误判的地方'],rows:[['零售信用','信用卡、消费贷、按揭的迁徙与回收','零售品牌强不代表所有产品风险低'],['企业信用','行业与客户集中、现金流、担保结构','贷款利率高不等于风险后回报高'],['房地产相关','开发贷、按揭、投资和表外风险','只看开发贷余额会遗漏其他暴露'],['核销和处置','现金回收、出售折价、核销后的追偿','不良率下降不一定由借款人恢复偿还'],['信用减值','新形成、存量变化、模型参数和宏观假设','较低信用成本不能直接当长期正常值']]}},
      {p:'对招商银行，期末不良率稳定而关注占比上升，应该触发对迁徙和分产品表现的跟踪，而不是直接宣布资产质量恶化或改善。[S1] 缺少可比回收率、抵押品估值和未来损失分布时，无法精确判断最终损失；保留区间与资本缓冲，比给一个无依据的“正常信用成本”更诚实。'}]},
    {id:'capital',title:'五、资本与分红：净利润不是派息上限',sub:'留存收益需要支持风险资产、缓冲和业务韧性',blocks:[
      {p:'银行的增长受到资本约束。研究分配能力时，应从普通股归属利润出发，扣除支持风险加权资产增长所需资本和必要缓冲，核对其他资本工具的分配、母公司法律可分配利润和实际现金安排。发行资本工具可以改变某一比率，但不是免费创造普通股价值，也不能永久依赖融资维持高派息。'},
      {p:'在固定风险密度与资本目标的简化情景下，新增风险加权资产乘目标核心一级资本比率，是资本占用的一个起点；真实计算还受监管扣除、资产风险迁徙、内评法、分红和非利润变动影响。这只是说明增长与派息必须联立，不是精确监管测算。本报告未建立全行业逐年资本预算，也不替公司承诺未来十年派息。'},
      {bullets:['看实际资本净额和风险加权资产，不只看一个资本充足率。比率下降可能来自分母增长或风险变化。','年度与中期股息需核董事会、股东会、除息日和实施状态；有政策意向不代表买入后全部有权领取。','优先普通股口径。归母权益与普通股权益可能因其他权益工具不同，ROE、EPS和PB必须使用对应分母。','若信用损失增加、资本目标提高或融资受限，先重估分红，而不是只下调增长还维持原高派息。']},
      {p:'招行高级法核心一级资本充足率较上年末下降0.09个百分点，不证明资本危机，也不能据其高于最低要求就认定全部差额可用于回购或分红。[S1] 对股东重要的是银行在不利信用周期中仍能保护资本、客户服务和长期每股回报。'}]},
    {id:'wealth',title:'六、财富管理与科技：服务优势要用经济结果验证',sub:'AUM、交易量和AI投入不等于利润或现金',blocks:[
      {p:'财富管理降低单一利差收入依赖，但其收费与市场、产品结构及客户行为有关。资产管理规模增加，可能来自价格上涨、新资金流入或统计范围变化；只有拆开收费资产、费率与成本，才能判断经营质量。银行代销基金、保险与理财的客户资产，不是可以计入银行净资产的自有现金。'},
      {p:'支付、结算与服务可能形成客户黏性，但误售、过度追逐手续费会损伤这种关系。长期优势来自让客户在多个市场周期中得到可信服务，而不是单年手续费最大化。研究应问：客户是否持续把主要支付和财富关系留在这里？新增服务收入是否需要不成比例的营销、补贴或合规成本？'},
      {p:'AI可以降低部分人工流程成本、改善反欺诈和客户服务，也可能产生数据安全、模型误判与管理成本。应用数量、Token和“节省工时”不能直接等于归母利润。需要净成本节约、可控风险、服务结果和可重复收入证据；没有桥接时，不给科技叙事单独加估值倍数。'}]},
    {id:'differences',title:'七、银行之间怎样比较？',sub:'不以招行样本推断每一家银行',blocks:[
      {table:{head:['类型','研究重点','无法省略的风险'],rows:[['全国性大型银行','负债稳定、业务广度、资本分配与资产结构','低利率、政策性投放与大型信用暴露'],['优质零售/综合股份行','客户服务、资金成本、财富收入、风险定价','零售信用压力和市场相关收入波动'],['区域银行','当地经济、客户集中、治理与资金来源','地理集中、地产/地方产业风险和治理'],['高增长银行','风险后资本回报与留存资金效率','快速增长掩盖贷款成熟期和损失滞后']]}},
      {p:'这是比较框架而非对上述类型的统一评级。个别银行可能跨越这些边界，地方经济强也不能替代逐项财报核验。可比PB需要同一天股价、同一普通股净资产口径和市场币种；上市A/H股权利与价格不同，不能用A价乘A/H总股数声称得到实际合计市值。'},
      {p:'研究顺序应是业务、风险、资本与治理，再是相对价格。把所有银行的PE压到一个水平后选最低值，容易奖励暂时少计信用成本或资本压力更大的公司。相反，给历史ROE高的银行永久高估值，也忽略了客户风险、收入结构和资本基数的变化。'}]},
    {id:'valuation',title:'八、估值：用正常化ROE解释PB，而不是反过来',sub:'估值关系有条件，不是目标价生成器',blocks:[
      {p:'在清洁盈余、稳定ROE、稳定增长与分配、股权资本成本高于增长率等假设下，PB与(ROE−增长率)/(股权资本成本−增长率)的关系，可用来理解为什么低PB既可能便宜，也可能合理。[S2] 若银行长期资本回报低于股东机会成本，账面净资产折价不奇怪。反之，能够稳健产生超额回报且分配可信的银行，账面值只是价值的起点。'},
      {p:'这些条件在现实里经常不稳定：净资产有估值与扣除变化，信用损失跨周期，股本可能变化，监管资本与会计资本不同。不能拿半年度年化ROE、任意长期增速和统一折现率直接算“精确合理PB”。应先解释正常化利润，再检查资产质量、资本需求和每股权益；价格判断最后进行。'},
      {bullets:['股利现金流是股东实际分配路径的一种主线；银行不能照搬工业企业经营现金减厂房投资作为FCFE。','剩余收益法作为经济交叉检查：看每年普通股资本创造是否超过机会成本，而非重复加入同一利润。','利润倍数需使用正常化信用成本，并检查其与净资产、ROE一致。低PE不排除盈利高估。','高股息率需要同日价格和实际股息权利；本文不提供未经刷新行情支持的当前买入排名。']}]},
    {id:'scenarios',title:'九、情景研究：把信用、息差和资本联立',sub:'不填无依据的统一增长率或统一分红率',blocks:[
      {table:{head:['条件情景','经营路径','估值与分配应怎样响应'],rows:[['压力','息差下降，零售损失增加，风险资产增长快于资本创造','降低正常化利润与可分配比例；提高安全边际'],['基准','存款重定价部分抵消贷款降价，信用成本可控，收费业务稳健','只把可解释的每股资本创造与分红延续纳入'],['改善','真实需求、风险定价与服务收入改善，不依赖拨备一次性释放','验证持续性后再改善长期回报假设']]}},
      {p:'本表是研究条件，不是未来预测或情景概率。不会为了让银行排在榜单前面而降低回报要求，也不把招商银行当前的年化ROE作为所有银行的基准。真正有用的压力测试是：盈利下降时是否必须减派息或补资本？如果答案是肯定的，收入和分红模型不能彼此独立。'},
      {p:'长期判断变化应来自新证据。一次利润超预期若主要由税率、处置或金融资产估值贡献，不能自动调高未来增长。相反，银行主动少做风险贷款导致规模增长放缓，可能保护长期每股回报；需要解释经济结果，不能只用增长大小评优劣。'}]},
    {id:'risks',title:'十、风险与投资者视角',sub:'品牌信任和资本纪律重要，但无法消除杠杆风险',blocks:[
      {bullets:['信用损失滞后：逾期、展期和重组可能晚于利润变化暴露，当前损失率不能永久化。','利率与久期：资产负债重定价、债券估值和客户行为可能同时变化。','资本和治理：关联交易、股东诉求、资本工具成本以及对扩张的约束。','合规与运营：支付、数据、模型、误售和声誉事件可能损伤低成本客户关系。','估值风险：低倍数并不保证价值，高分红也不能抵消本金与资本创造恶化。']},
      {p:'用巴菲特式视角研究，重点是可信管理、存款优势和跨周期资本回报；用芒格式视角，先倒推会造成不可逆损失的杠杆、激励和认知盲区。段永平式视角要求真正理解客户关系与风险，而不是因为“银行便宜”就越过能力圈。散户乙式视角需要把价格与经得起压力的实际分配联系起来。韦尔奇式经营视角关注风险文化、流程效率与业务取舍。这些是框架推演，不代表五位投资者对该行业的当前言论或持仓。'}]},
    {id:'verify',title:'十一、什么证据会改变判断？',sub:'把下次研究变成可检验的工作，而不是重复观点',blocks:[
      {numbered:['逐期记录集团净息差与资产、负债收益/成本，分清量和价；不只看期末存款。','跟踪零售与对公贷款的关注、逾期、不良生成、核销和回收。统一集团或本行口径。','检查正常化信用成本下的普通股ROE、每股净资产创造和资本净额，剔除不可重复项。','把风险加权资产路径、资本目标与分红联立；核中期股息批准及实际权利。','核财富管理净流入、收费基数和成本，区分客户资产与银行自有资产。','下一轮价格判断重新取同日A/H行情和每股权益；不要用行业报告日期冒称行情已刷新。']},
      {p:'更积极的证据是低成本客户关系稳定、风险后资本回报有韧性且分配不依赖削弱缓冲；更谨慎的证据是新风险持续迁徙、资本创造落后于占用、长期分红必须靠融资支撑。行业研究的价值是识别这些条件，不是给全部银行发同一张“低PB买入”许可证。'}]}
  ],
  sources:[['S1 · 招商银行2026年半年度报告','2026-08-28披露；集团2026H1及期末，PDF7/9/23/30页；原表渲染复核','https://pdf.dfcfw.com/pdf/H2_AN202608281828637732_1.pdf'],['S2 · Damodaran市净率决定因素','ROE、增长与资本成本的条件关系；方法参考，不是中国银行行情','https://pages.stern.nyu.edu/~adamodar/New_Home_Page/invfables/pbvdeterminants.htm']],
  sourcesNote:'截至2026年10月1日的本地研究。妙想先取数与公告，再下载公司原始PDF核表；行业自动稿只作线索，其未核宏观数字未写入正文。样本为招行，不代表上市银行平均；没有重新取全行业实时估值、没有估计未来信用损失概率。金额为人民币，时点、累计与年化分别列示；框架和条件讨论为独立研究推演。',
  disclaimer:'本报告不构成个人投资建议，不保证本金、分红或回报。此次仅新增本地行业正文，不修改个股价格、模型、排名或投资者详细点评；更新需重新核原始披露。',
  sourceFile:{href:'reports/industries/银行行业-20261001.md',format:'Markdown'}
};


